class Solution {
public:
    int countPaths(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        int MOD = 1e9 + 7;
        std::vector<std::vector<int>> memo(m, std::vector<int>(n, -1));
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        auto dfs = [&](auto& self, int r, int c) -> int {
            if (memo[r][c] != -1) return memo[r][c];
            long long res = 1;
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] > grid[r][c]) {
                    res = (res + self(self, nr, nc)) % MOD;
                }
            }
            return memo[r][c] = res;
        };
        long long ans = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                ans = (ans + dfs(dfs, r, c)) % MOD;
            }
        }
        return ans;
    }
};

class Solution {
    private static final int MOD = 1_000_000_007;
    private int[][] memo;
    private int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    public int countPaths(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        memo = new int[m][n];
        long ans = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                ans = (ans + dfs(grid, r, c, m, n)) % MOD;
            }
        }
        return (int) ans;
    }
    private int dfs(int[][] grid, int r, int c, int m, int n) {
        if (memo[r][c] != 0) return memo[r][c];
        long res = 1;
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] > grid[r][c]) {
                res = (res + dfs(grid, nr, nc, m, n)) % MOD;
            }
        }
        return memo[r][c] = (int) res;
    }
}

var countPaths = function(grid) {
    const m = grid.length, n = grid[0].length;
    const MOD = 1000000007;
    const memo = Array.from({ length: m }, () => new Array(n).fill(-1));
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    function dfs(r, c) {
        if (memo[r][c] !== -1) return memo[r][c];
        let res = 1;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] > grid[r][c]) {
                res = (res + dfs(nr, nc)) % MOD;
            }
        }
        return memo[r][c] = res;
    }
    let ans = 0;
    for (let r = 0; r < m; ++r) {
        for (let c = 0; c < n; ++c) {
            ans = (ans + dfs(r, c)) % MOD;
        }
    }
    return ans;
};
